  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'अपने सभी रिकॉर्ड (ग्राहक, प्रोडक्ट, बिल, भुगतान, खर्च और स्टॉक) की एक कॉपी CSV फ़ाइलों की ZIP में डाउनलोड करें, फिर शेयर शीट से सहेजें या भेजें। इसे सुरक्षित रखें। FlowXP इससे अपने-आप बहाल नहीं करता: डेटा वापस चाहिए तो सपोर्ट से कहें।',
