  'E-invoicing applies to businesses above a turnover limit and only for sales to customers with a GSTIN. If it does not apply to you, ignore this tab.': 'ई-इनवॉइसिंग एक टर्नओवर सीमा से ऊपर के व्यवसायों पर और केवल GSTIN वाले ग्राहकों को बिक्री पर लागू होती है। आप पर लागू न हो तो इस टैब को अनदेखा करें।',
