  'Offers and reminders only go to customers who have not opted out. Bills and booking messages are service messages and are sent regardless.': 'ऑफ़र और रिमाइंडर केवल उन ग्राहकों को जाते हैं जिन्होंने मना नहीं किया है। बिल और बुकिंग संदेश सेवा संदेश हैं और हर हाल में भेजे जाते हैं।',
  'Show the WhatsApp templates to create in Meta': 'Meta में बनाने के लिए व्हाट्सऐप टेम्पलेट दिखाएँ',
  'Hide the WhatsApp templates': 'व्हाट्सऐप टेम्पलेट छिपाएँ',
