  // Printers
  'Bluetooth and Wi-Fi printers: receipt and kitchen ticket': 'ब्लूटूथ और वाई-फ़ाई प्रिंटर: रसीद और किचन टिकट',
  'Connect a Bluetooth or Wi-Fi thermal printer, and choose what each one prints.': 'ब्लूटूथ या वाई-फ़ाई थर्मल प्रिंटर जोड़ें, और चुनें कि हर एक क्या छापे।',
  'Printing straight to a printer needs the FlowXP development app. In the Expo Go test copy, use the phone print screen or RawBT in Settings.': 'सीधे प्रिंटर पर छापने के लिए FlowXP का डेवलपमेंट ऐप चाहिए। Expo Go टेस्ट कॉपी में सेटिंग्स में फ़ोन प्रिंट स्क्रीन या RawBT इस्तेमाल करें।',
  'No printers yet.': 'अभी कोई प्रिंटर नहीं।',
