  'No Bluetooth printers found. Switch the printer on and pair it in the phone\'s Bluetooth settings.': 'कोई ब्लूटूथ प्रिंटर नहीं मिला। प्रिंटर चालू करें और फ़ोन की ब्लूटूथ सेटिंग्स में पेयर करें।',
