  'The port is a number from 1 to 65535 (most printers use 9100)': 'पोर्ट 1 से 65535 के बीच की संख्या है (ज़्यादातर प्रिंटर 9100 इस्तेमाल करते हैं)',
  'Allow FlowXP to use Bluetooth (nearby devices) in the phone settings, then try again.': 'फ़ोन सेटिंग्स में FlowXP को ब्लूटूथ (आसपास के डिवाइस) की अनुमति दें, फिर दोबारा कोशिश करें।',
  'Switch Bluetooth on, then try again.': 'ब्लूटूथ चालू करें, फिर दोबारा कोशिश करें।',
