  'Could not reach the printer. Check that it is switched on, on the same Wi-Fi as this phone, and that the address is right.': 'प्रिंटर तक नहीं पहुँच सके। देखें कि वह चालू है, इस फ़ोन के वाई-फ़ाई पर है और पता सही है।',
