  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'शुद्ध राजस्व वह है जो कर से पहले बिल हुआ, छूट और रिफ़ंड घटाकर। रद्द बिल छोड़ दिए जाते हैं। खाने की लागत वह सामग्री-लागत है जो हर बिल बनते समय दर्ज हुई। शुल्क, कमीशन और पैकेजिंग आपकी धारणाओं पर चलते हैं: तय न हो तो शून्य। योगदान वह है जो हर बिक्री किराये, वेतन और अन्य स्थायी खर्चों के लिए छोड़ती है।',
